{
  "jsonrpc": "2.0",
  "id": 8,
  "result": {
    "resultType": "complete",
    "tools": [
      {
        "name": "get_status",
        "description": "Returns the operational status of the agentic engine.",
        "inputSchema": {
          "type": "object",
          "properties": {},
          "required": []
        }
      }
    ]
  }
}

{
  "jsonrpc": "2.0",
  "id": 10,
  "result": {
    "resultType": "complete",
    "content": [{ "type": "text", "text": "4 function(s) available." }],
    "structuredContent": {
      "functions": [
        {
          "name": "vehicle_detection",
          "canonicalUri": "https://vendor.example/agentic/function/vehicle_detection",
          "description": "Detect and classify vehicles in the scene.",
          "enabled": true,
          "configSchema": "https://vendor.example/agentic/linkml/#/$defs/VehicleDetectionConfig"
        },
        {
          "name": "vehicle_reidentification",
          "canonicalUri": "https://vendor.example/agentic/function/vehicle_reidentification",
          "description": "Assert that vehicle observations refer to the same physical vehicle.",
          "enabled": true,
          "configSchema": "https://vendor.example/agentic/linkml/#/$defs/VehicleReidentificationConfig"
        },
        {
          "name": "license_plate_recognition",
          "canonicalUri": "https://vendor.example/agentic/function/license_plate_recognition",
          "description": "Read license plates of detected vehicles.",
          "enabled": false,
          "configSchema": "https://vendor.example/agentic/linkml/#/$defs/LicensePlateRecognitionConfig"
        },
        {
          "name": "set_event_stream_parameters",
          "canonicalUri": "https://www.onvif.org/ver10/agentic/function/set_event_stream_parameters",
          "description": "Set the keep-alive interval of the event stream.",
          "enabled": true,
          "executionSchema": "https://www.onvif.org/ver10/agentic/linkml/#/$defs/SetEventStreamParametersRequest",
          "resultSchema": "https://www.onvif.org/ver10/agentic/linkml/#/$defs/SetEventStreamParametersResponse",
          "capabilitiesSchema": "https://www.onvif.org/ver10/agentic/linkml/#/$defs/EventStreamCapabilities"
        }
      ]
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": 14,
  "result": {
    "resultType": "complete",
    "content": [{ "type": "text", "text": "Requested 1000 ms clamped to the device minimum." }],
    "structuredContent": {
      "@type": "onvif:SetEventStreamParametersResponse",
      "executionId": "exec_keepalive_002",
      "appliedKeepaliveIntervalMs": 5000,
      "clamped": true,
      "affectedStreams": [30]
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": 20,
  "result": {
    "events": [
      {
        "name": "VehicleObservation",
        "canonicalUri": "https://www.onvif.org/ver10/agentic/linkml/VehicleObservation",
        "description": "Emitted when the vehicle detection function observes a vehicle",
        "delivery": ["push", "webhook"],
        "inputSchema": {
          "type": "object",
          "properties": {
            "locationToken": {
              "type": "string",
              "description": "Token of a configured location to filter on"
            }
          }
        },
        "payloadSchema": {
          "$ref": "https://www.onvif.org/ver10/agentic/base/linkml/#/$defs/InformationEnvelope"
        }
      },
      {
        "name": "VehicleReidentification",
        "canonicalUri": "https://www.onvif.org/ver10/agentic/linkml/VehicleReidentification",
        "description": "Emitted when two vehicle observations are found to be of the same vehicle",
        "delivery": ["push", "webhook"],
        "inputSchema": {
          "type": "object",
          "properties": {
            "locationToken": {
              "type": "string",
              "description": "Token of a configured location to filter on"
            }
          }
        },
        "payloadSchema": {
          "$ref": "https://www.onvif.org/ver10/agentic/base/linkml/#/$defs/InformationEnvelope"
        }
      }
    ]
  }
}

