{
  "jsonrpc": "2.0",
  "id": 21,
  "result": {
    "resultType": "complete",
    "content": [{ "type": "text",
                  "text": "Limits 10.0-130.0 km/h, tolerance up to 10.0 km/h, 4 concurrent executions." }],
    "structuredContent": {
      "function": "speeding_assessment",
      "capabilities": {
        "@type": "hackathon2026:SpeedingAssessmentCapabilities",
        "minimumSpeedLimit": 10.0,
        "maximumSpeedLimit": 130.0,
        "maximumTolerance": 10.0,
        "supportsDryRun": true,
        "maximumConcurrentExecutions": 4
      }
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": 22,
  "result": {
    "resultType": "complete",
    "content": [{ "type": "text", "text": "speeding_assessment configured: limit 50.0 km/h, tolerance 3.0 km/h." }],
    "structuredContent": {
      "function": "speeding_assessment",
      "applied": {
        "@type": "hackathon2026:SpeedingAssessmentConfig",
        "speedLimit": 50.0,
        "tolerance": 3.0,
        "rule": "urn:onvif-hackathon:rule:urban-speed-limit",
        "minimumConfidence": 0.75,
        "emitOnlyWhenExceeded": true
      }
    }
  }
}
